window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-738c3a7445da1d3a"]={"versions": [{"id": "FIG-738c3a7445da1d3a", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Zeitablauf- und Semantikdiagramm zur Veranschaulichung des Logical Execution Time (LET)-Ansatzes innerhalb der AUTOSAR Timing Extensions (AUTOSAR CP). Das Diagramm stellt das Verhältnis zwischen der zeitdeterministischen logischen Abstraktionsebene („Logical“) und dem realen, verdrängenden Ablauf auf Task- und OS-Ebene („Physical“) gegenüber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet zwei Betrachtungsebenen:</p>\n<ul class=\"fig-list\"><li><strong>Logical:</strong> Repräsentiert das LET-Intervall als zusammenhängendes Zeitfenster fester Dauer, begrenzt durch die Zeitpunkte <code>Release</code> (logischer Eingabezeitpunkt) und <code>Terminate</code> (logischer Ausgabezeitpunkt).\n</li><li><strong>Physical:</strong> Reale Ausführungsebene mit Ereignissen und Zuständen:\n<ul class=\"fig-list\"><li>Ereignisse: <code>Activate</code> (Task-Aktivierung), <code>Start</code> (tatsächlicher Rechenbeginn), <code>Terminate</code> (physisches Ausführungsende).\n</li><li>Zustände (Legende):\n<ul class=\"fig-list\"><li><code>Execution</code> (blau ausgefüllter Block): Aktive Rechenzeit auf der CPU.\n</li><li><code>Suspended</code> (hellblau gepunkteter Block): Unterbrechung/Verdrängung (Preemption/Wartezeit).\n</li><li><code>Reading/Writing Data Filling/Flushing Buffer</code> (gelb ausgefüllter Block): Pufferoperationen zum Einlesen bzw. Bereitstellen der Kommunikationsdaten.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Logische Ebene:</strong>\n<ul class=\"fig-list\"><li>Mit dem Erreichen des logischen <code>Release</code>-Zeitpunkts stehen die Eingangsdaten fest; die Daten werden in den Puffer eingelesen (<code>Reading/Writing Data Filling/Flushing Buffer</code>).\n</li><li>Das Intervall <code>Logical Execution Time</code> läuft über eine feste Soll-Dauer bis zum logischen <code>Terminate</code>-Zeitpunkt.\n</li><li>Am logischen <code>Terminate</code>-Zeitpunkt werden die Ausgangsdaten aus dem Puffer bereitgestellt/geschrieben (<code>Reading/Writing Data Filling/Flushing Buffer</code>).\n</li></ul>\n</li><li><strong>Physische Ebene:</strong>\n<ul class=\"fig-list\"><li>Synchron zum logischen <code>Release</code> erfolgt das Ereignis <code>Activate</code> der zugehörigen Task/des Runnables.\n</li><li>Nach einer Latenz startet die physische Ausführung (<code>Start</code>).\n</li><li>Während des Laufs wechseln Phasen aktiver Ausführung (<code>Execution</code>) und Verdrängung/Unterbrechung (<code>Suspended</code>).\n</li><li>Die physische Berechnung endet mit <code>Terminate</code> noch vor Ablauf der logischen Zeitspanne.\n</li><li>Die Ausgabe der Daten an nachfolgende Empfänger bleibt trotz früherem physischen Ausführungsende bis zum Erreichen des logischen <code>Terminate</code>-Punkts verzögert.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Gemäß <code>[constr_4558]</code> ist die LET-Semantik ausschließlich auf implizite Sender-Receiver-Kommunikation anwendbar.\n</li><li>Das LET-Intervall wird im Timing-Modell über eine <code>TimingDescriptionEventChain</code> mit Attribut <code>category = LET_INTERVAL</code> modelliert.\n</li><li>Das Stimulus-Event (<code>category = LET_RELEASE</code>) markiert den Freigabezeitpunkt, das Response-Event (<code>category = LET_TERMINATE</code>) den Beendigungszeitpunkt; zur Modellierung wird <code>TDEventComplex</code> herangezogen.\n</li><li>Entwickler müssen sicherstellen, dass die Worst-Case Execution Time (WCET) zuzüglich aller Verdrängungszeiten (<code>Suspended</code>) die definierte <code>Logical Execution Time</code> nicht überschreitet, um einen Deadline-Bruch vor dem <code>Terminate</code>-Zeitpunkt zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b86e094601914ca8", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Zeitablauf- und Semantikdiagramm zur Veranschaulichung des Logical Execution Time (LET)-Ansatzes innerhalb der AUTOSAR Timing Extensions (AUTOSAR CP). Das Diagramm stellt das Verhältnis zwischen der zeitdeterministischen logischen Abstraktionsebene („Logical“) und dem realen, verdrängenden Ablauf auf Task- und OS-Ebene („Physical“) gegenüber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet zwei Betrachtungsebenen:</p>\n<ul class=\"fig-list\"><li><strong>Logical:</strong> Repräsentiert das LET-Intervall als zusammenhängendes Zeitfenster fester Dauer, begrenzt durch die Zeitpunkte <code>Release</code> (logischer Eingabezeitpunkt) und <code>Terminate</code> (logischer Ausgabezeitpunkt).\n</li><li><strong>Physical:</strong> Reale Ausführungsebene mit Ereignissen und Zuständen:\n<ul class=\"fig-list\"><li>Ereignisse: <code>Activate</code> (Task-Aktivierung), <code>Start</code> (tatsächlicher Rechenbeginn), <code>Terminate</code> (physisches Ausführungsende).\n</li><li>Zustände (Legende):\n<ul class=\"fig-list\"><li><code>Execution</code> (blau ausgefüllter Block): Aktive Rechenzeit auf der CPU.\n</li><li><code>Suspended</code> (hellblau gepunkteter Block): Unterbrechung/Verdrängung (Preemption/Wartezeit).\n</li><li><code>Reading/Writing Data Filling/Flushing Buffer</code> (gelb ausgefüllter Block): Pufferoperationen zum Einlesen bzw. Bereitstellen der Kommunikationsdaten.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Logische Ebene:</strong>\n<ul class=\"fig-list\"><li>Mit dem Erreichen des logischen <code>Release</code>-Zeitpunkts stehen die Eingangsdaten fest; die Daten werden in den Puffer eingelesen (<code>Reading/Writing Data Filling/Flushing Buffer</code>).\n</li><li>Das Intervall <code>Logical Execution Time</code> läuft über eine feste Soll-Dauer bis zum logischen <code>Terminate</code>-Zeitpunkt.\n</li><li>Am logischen <code>Terminate</code>-Zeitpunkt werden die Ausgangsdaten aus dem Puffer bereitgestellt/geschrieben (<code>Reading/Writing Data Filling/Flushing Buffer</code>).\n</li></ul>\n</li><li><strong>Physische Ebene:</strong>\n<ul class=\"fig-list\"><li>Synchron zum logischen <code>Release</code> erfolgt das Ereignis <code>Activate</code> der zugehörigen Task/des Runnables.\n</li><li>Nach einer Latenz startet die physische Ausführung (<code>Start</code>).\n</li><li>Während des Laufs wechseln Phasen aktiver Ausführung (<code>Execution</code>) und Verdrängung/Unterbrechung (<code>Suspended</code>).\n</li><li>Die physische Berechnung endet mit <code>Terminate</code> noch vor Ablauf der logischen Zeitspanne.\n</li><li>Die Ausgabe der Daten an nachfolgende Empfänger bleibt trotz früherem physischen Ausführungsende bis zum Erreichen des logischen <code>Terminate</code>-Punkts verzögert.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Gemäß <code>[constr_4558]</code> ist die LET-Semantik ausschließlich auf implizite Sender-Receiver-Kommunikation anwendbar.\n</li><li>Das LET-Intervall wird im Timing-Modell über eine <code>TimingDescriptionEventChain</code> mit Attribut <code>category = LET_INTERVAL</code> modelliert.\n</li><li>Das Stimulus-Event (<code>category = LET_RELEASE</code>) markiert den Freigabezeitpunkt, das Response-Event (<code>category = LET_TERMINATE</code>) den Beendigungszeitpunkt; zur Modellierung wird <code>TDEventComplex</code> herangezogen.\n</li><li>Entwickler müssen sicherstellen, dass die Worst-Case Execution Time (WCET) zuzüglich aller Verdrängungszeiten (<code>Suspended</code>) die definierte <code>Logical Execution Time</code> nicht überschreitet, um einen Deadline-Bruch vor dem <code>Terminate</code>-Zeitpunkt zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-738c3a7445da1d3a", "to": "FIG-b86e094601914ca8", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
